exercise.solution:
interface TaskRepository {
    findAll(): Task[];
    findById(id: number): Task | undefined;
    save(task: Task): Task;
}

interface Task {
    id: number;
    title: string;
    done: boolean;
}

class InMemoryTaskRepository implements TaskRepository {
    private tasks: Task[] = [];
    private nextId = 1;

    findAll(): Task[] {
        return [...this.tasks];
    }

    findById(id: number): Task | undefined {
        return this.tasks.find(task => task.id === id);
    }

    save(task: Task): Task {
        if (task.id === 0) {
            task = { ...task, id: this.nextId++ };
            this.tasks.push(task);
            return task;
        }

        const index = this.tasks.findIndex(existing => existing.id === task.id);
        if (index >= 0) {
            this.tasks[index] = task;
        } else {
            this.tasks.push(task);
        }
        return task;
    }
}

class ConflictError extends Error {
    constructor(message: string) {
        super(message);
        this.name = "ConflictError";
    }
}

class NotFoundError extends Error {
    constructor(message: string) {
        super(message);
        this.name = "NotFoundError";
    }
}

class TaskService {
    constructor(private repository: TaskRepository) {
    }

    create(title: string): Task {
        const trimmedTitle = title.trim();
        const exists = this.repository.findAll()
            .some(task => task.title.toLowerCase() === trimmedTitle.toLowerCase());

        if (exists) {
            throw new ConflictError("Task already exists");
        }

        return this.repository.save({
            id: 0,
            title: trimmedTitle,
            done: false
        });
    }

    complete(id: number): Task {
        const task = this.repository.findById(id);

        if (!task) {
            throw new NotFoundError("Task not found");
        }

        if (task.done) {
            throw new ConflictError("Task is already done");
        }

        return this.repository.save({
            ...task,
            done: true
        });
    }
}

